package com.palash.opencodeserver.backend.api

import com.squareup.moshi.Json
import com.squareup.moshi.JsonClass

/**
 * Typed request/response models for the OpenCode HTTP API.
 *
 * These mirror the server's OpenAPI 3.1 contract. Every field is nullable or defaulted so an older
 * or newer server release cannot crash the client on deserialization (spec 21): unknown shapes are
 * dropped and a compatibility warning is raised instead of an exception.
 *
 * Adapters are generated by KSP (`generateAdapter = true`) rather than reflectively, which avoids
 * pulling `kotlin-reflect` into the runtime and keeps parse failures explicit.
 *
 * Reference: `/global/health`, `/session`, `/session/{id}/message`, `/file`, `/provider`,
 * `/config`, `/event`. The authoritative shape is always the running server's `/doc` spec, which
 * the API version gate reads at runtime (spec 91).
 */

// ---- global --------------------------------------------------------------------------------

@JsonClass(generateAdapter = true)
data class HealthResponse(
    val healthy: Boolean? = null,
    val version: String? = null
)

// ---- project / path ------------------------------------------------------------------------

@JsonClass(generateAdapter = true)
data class OcProject(
    val id: String? = null,
    val worktree: String? = null,
    val vcsDir: String? = null,
    val vcs: String? = null,
    val time: OcTime? = null
) {
    val resolvedId: String get() = id.orEmpty()
    val resolvedWorktree: String get() = worktree.orEmpty()
}

@JsonClass(generateAdapter = true)
data class OcTime(val created: Long? = null, val updated: Long? = null, val initialized: Long? = null)

@JsonClass(generateAdapter = true)
data class OcPath(
    val state: String? = null,
    val config: String? = null,
    val worktree: String? = null,
    val directory: String? = null
)

@JsonClass(generateAdapter = true)
data class OcVcsInfo(val branch: String? = null)

// ---- sessions ------------------------------------------------------------------------------

@JsonClass(generateAdapter = true)
data class OcSession(
    val id: String? = null,
    val projectID: String? = null,
    val directory: String? = null,
    val parentID: String? = null,
    val title: String? = null,
    val version: String? = null,
    val time: OcTime? = null,
    val summary: OcSessionSummary? = null,
    val share: OcShare? = null
) {
    val resolvedId: String get() = id.orEmpty()
    val resolvedTitle: String get() = title?.takeIf { it.isNotBlank() } ?: "Untitled session"
    val createdAtMs: Long get() = (time?.created ?: 0L)
    val updatedAtMs: Long get() = (time?.updated ?: time?.created ?: 0L)
}

@JsonClass(generateAdapter = true)
data class OcSessionSummary(
    val additions: Int? = null,
    val deletions: Int? = null,
    val files: Int? = null,
    val diffs: List<OcFileDiff>? = null
)

@JsonClass(generateAdapter = true)
data class OcShare(val url: String? = null)

@JsonClass(generateAdapter = true)
data class OcSessionCreateRequest(
    val parentID: String? = null,
    val title: String? = null
)

@JsonClass(generateAdapter = true)
data class OcSessionUpdateRequest(val title: String? = null)

/** `GET /session/status` -> map of sessionID to status. */
@JsonClass(generateAdapter = true)
data class OcSessionStatus(
    val type: String? = null,
    val attempt: Int? = null,
    val message: String? = null,
    val next: Long? = null
) {
    val isIdle: Boolean get() = type == "idle"
    val isBusy: Boolean get() = type == "busy"
    val isRetrying: Boolean get() = type == "retry"
}

// ---- messages ------------------------------------------------------------------------------

@JsonClass(generateAdapter = true)
data class OcMessageWithParts(
    val info: OcMessage? = null,
    val parts: List<OcPart>? = null
)

/**
 * Union member. `role` and `error` are kept as raw maps so an unfamiliar assistant-message shape
 * from a newer server degrades to a generic message rather than a parse failure.
 */
@JsonClass(generateAdapter = true)
data class OcMessage(
    val id: String? = null,
    val sessionID: String? = null,
    val role: String? = null,
    val parentID: String? = null,
    val modelID: String? = null,
    val providerID: String? = null,
    val mode: String? = null,
    val agent: String? = null,
    val time: OcMessageTime? = null,
    val error: OcMessageError? = null,
    val finish: String? = null,
    val cost: Double? = null,
    val tokens: OcTokens? = null
)

@JsonClass(generateAdapter = true)
data class OcMessageTime(val created: Long? = null, val completed: Long? = null)

@JsonClass(generateAdapter = true)
data class OcTokens(
    val input: Long? = null,
    val output: Long? = null,
    val reasoning: Long? = null,
    val cache: OcCacheTokens? = null
)

@JsonClass(generateAdapter = true)
data class OcCacheTokens(val read: Long? = null, val write: Long? = null)

@JsonClass(generateAdapter = true)
data class OcMessageError(
    val name: String? = null,
    val data: Map<String, Any?>? = null
) {
    /** Extract a human message from the nested error payload. */
    fun messageText(): String? {
        val raw = data?.get("message")?.toString()
        return raw?.takeIf { it.isNotBlank() }
    }

    val isAborted: Boolean get() = name?.contains("Aborted", ignoreCase = true) == true
    val isAuthProblem: Boolean get() = name?.contains("ProviderAuth", ignoreCase = true) == true
}

/**
 * Union member for message parts.
 *
 * `state` is intentionally a raw map: the tool-state union (`pending`/`running`/`completed`/
 * `error`) is read through [toolStatus] rather than a nested sealed class, which keeps the client
 * forward compatible with new tool states.
 */
@JsonClass(generateAdapter = true)
data class OcPart(
    val id: String? = null,
    val sessionID: String? = null,
    val messageID: String? = null,
    val type: String? = null,
    // text
    val text: String? = null,
    // reasoning
    // file
    val mime: String? = null,
    val filename: String? = null,
    val url: String? = null,
    // tool
    val callID: String? = null,
    val tool: String? = null,
    val state: Map<String, Any?>? = null,
    // patch
    val files: List<String>? = null,
    // agent / subtask
    val name: String? = null,
    val prompt: String? = null,
    val description: String? = null,
    // retry
    val attempt: Int? = null,
    val error: OcMessageError? = null
) {
    val isText: Boolean get() = type == "text"
    val isReasoning: Boolean get() = type == "reasoning"
    val isTool: Boolean get() = type == "tool"
    val isFile: Boolean get() = type == "file"
    val isPatch: Boolean get() = type == "patch"
    val isAgent: Boolean get() = type == "agent"
    val isRetry: Boolean get() = type == "retry"
    val isStepStart: Boolean get() = type == "step-start"
    val isStepFinish: Boolean get() = type == "step-finish"

    fun toolStatus(): String? = state?.get("status")?.toString()

    fun toolTitle(): String? = state?.get("title")?.toString()

    fun toolOutput(): String? = state?.get("output")?.toString()

    fun toolError(): String? = state?.get("error")?.toString()
}

