// ---- events --------------------------------------------------------------------------------

/**
 * Spec 22/70 - one event from `GET /event`.
 *
 * `type` and `properties` are the two fields the whole event system is built on, so they are the
 * only ones mapped strictly; `properties` stays a map so a new event type from a newer server can
 * still be surfaced to the UI instead of being dropped (spec 70).
 */
@JsonClass(generateAdapter = true)
data class OcEvent(
    val type: String? = null,
    val properties: Map<String, Any?>? = null
) {
    val resolvedType: String get() = type.orEmpty()

    fun string(key: String): String? = properties?.get(key)?.toString()

    fun map(key: String): Map<String, Any?>? = properties?.get(key) as? Map<String, Any?>

    fun boolean(key: String): Boolean? = when (val raw = properties?.get(key)) {
        is Boolean -> raw
        is String -> raw.toBooleanStrictOrNull()
        else -> null
    }
}

/** Spec 41 example log line used when forwarding to the app log. */
@JsonClass(generateAdapter = true)
data class OcLogRequest(
    val service: String,
    val level: String,
    val message: String,
    val extra: Map<String, Any?>? = null
)